using System.Reflection;
namespace LSE.InventorFootprintTools;
public static class FootprintTransactionService{
 public static FootprintResult Execute(AppSettings s,NamingStandard n,PartNumberRequest pn,CatalogAddRequest q,FootprintGeometry g,string footprintDescription){
  PartNumberService.Validate(n.Format,pn);if(q.TableName.Length==0||q.Catalog.Length==0||q.Manufacturer.Length==0)throw new InvalidOperationException("Catalog table, Manufacturer and Catalog number are required.");if(q.Manufacturer.Length>24)throw new InvalidOperationException("MANUFACTURER is limited to 24 characters in the catalog.");if(q.Catalog.Length>60)throw new InvalidOperationException("CATALOG is limited to 60 characters.");if(q.Description.Length>150)throw new InvalidOperationException("DESCRIPTION is limited to 150 characters.");if(!File.Exists(s.CatalogPath))throw new FileNotFoundException("Catalog database was not found.",s.CatalogPath);if(!File.Exists(s.FootprintLookupPath))throw new FileNotFoundException("footprint_lookup.mdb was not found.",s.FootprintLookupPath);if(string.IsNullOrWhiteSpace(s.FootprintLibraryFolder))throw new InvalidOperationException("Footprint library folder is not set (Settings).");
  string backupRoot=Path.Combine(Path.GetDirectoryName(s.CatalogPath)??Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"LSE_Catalog_Backups");string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss");string backup=Path.Combine(backupRoot,stamp);Directory.CreateDirectory(backup);string catBackup=Path.Combine(backup,Path.GetFileName(s.CatalogPath)),fpBackup=Path.Combine(backup,Path.GetFileName(s.FootprintLookupPath));
  var log=new List<string>{$"Started: {DateTime.Now:s} by {Environment.UserName}@{Environment.MachineName}",$"Catalog: {s.CatalogPath}",$"Footprint lookup: {s.FootprintLookupPath}",$"Backup folder: {backup}",$"Record: {q.TableName} | {q.Manufacturer} | {q.Catalog} | prefix {pn.Prefix}"};
  using var gate=IssuanceLock.Acquire(s.CatalogPath,log);File.Copy(s.CatalogPath,catBackup,true);File.Copy(s.FootprintLookupPath,fpBackup,true);log.Add("Backups: PASS");VaultProbe.RequireWritable(VaultCatalogService.Enabled(s)?new[]{s.FootprintLookupPath}:new[]{s.FootprintLookupPath,s.CatalogPath});
  bool vault=false;string dxf="",dwg="";var result=new FootprintResult();
  try{var svc=new AccessCatalogService(s.CatalogPath);var existing=svc.ReadUser1StartingWith(pn.Prefix);string part=PartNumberService.Next(n.Format,pn.Prefix,existing);q.User1=part;result.PartNumber=part;log.Add($"Part number issued: {part} ({existing.Count} existing {pn.Prefix} value(s) scanned across all family tables)");
   if(svc.Exists(q.TableName,q.Manufacturer,q.Catalog))throw new InvalidOperationException("That manufacturer/catalog number already exists in the selected family.");
   Directory.CreateDirectory(s.FootprintLibraryFolder);dxf=Path.Combine(s.FootprintLibraryFolder,part+".dxf");dwg=Path.ChangeExtension(dxf,".dwg");if(File.Exists(dwg)||File.Exists(dxf))throw new InvalidOperationException("A footprint drawing already exists for "+part+" in "+s.FootprintLibraryFolder);
   DxfFootprintWriter.Write(dxf,g,s,new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"MFG",q.Manufacturer},{"CAT",q.Catalog},{s.LsePartAttribute,part}});result.DxfPath=dxf;log.Add($"Footprint DXF written: {dxf} ({g.Curves.Count} curve(s), {g.Width:0.###} x {g.Height:0.###} {g.Units})");
   if(s.ConvertToDwgWithAutoCad){AutoCadConvertService.DxfToDwg(dxf,dwg);result.DwgPath=dwg;log.Add("AutoCAD DXF to DWG: PASS "+dwg);}else log.Add("AutoCAD DXF to DWG: SKIPPED (setting is off). Save "+dxf+" as "+dwg+" before inserting the footprint.");
   if(VaultCatalogService.Enabled(s)){VaultCatalogService.Checkout(s,log);vault=true;log.Add("Vault checkout: PASS");}
   svc.AddRecord(q);if(!svc.Exists(q.TableName,q.Manufacturer,q.Catalog))throw new InvalidOperationException("Read-back verification failed after insert.");log.Add($"Catalog insert into {q.TableName} (USER1={part}): PASS");
   if(vault){VaultCatalogService.Checkin(s,$"Add electrical catalog component {q.Manufacturer} {q.Catalog} ({part})",log);log.Add("Vault checkin: PASS");}
   var fp=new FootprintLookupService(s.FootprintLookupPath);fp.EnsureTable(q.Manufacturer);fp.Upsert(q.Manufacturer,q.Catalog,dwg,footprintDescription);log.Add($"Footprint lookup [{q.Manufacturer}] {q.Catalog} -> {dwg}: PASS");
   log.Add("Status: SUCCESS");log.AddRange(VaultProbe.CheckinReminder(new[]{result.DxfPath,result.DwgPath,s.FootprintLookupPath,VaultCatalogService.Enabled(s)?"":s.CatalogPath}));File.WriteAllLines(Path.Combine(backup,"TransactionReport.txt"),log);result.Report=string.Join(Environment.NewLine,log);return result;}
  catch(Exception ex){log.Add("ERROR: "+ex);try{File.Copy(catBackup,s.CatalogPath,true);log.Add("Catalog rollback: PASS");}catch(Exception rx){log.Add("Catalog rollback: FAILED "+rx.Message);}try{File.Copy(fpBackup,s.FootprintLookupPath,true);log.Add("Footprint lookup rollback: PASS");}catch(Exception rx){log.Add("Footprint lookup rollback: FAILED "+rx.Message);}
   foreach(string f in new[]{dxf,dwg})if(f.Length>0&&File.Exists(f))try{File.Delete(f);log.Add("Removed "+f);}catch{}if(vault)try{VaultCatalogService.UndoCheckout(s,log);log.Add("Vault undo checkout: PASS");}catch(Exception vx){log.Add("Vault undo checkout: FAILED "+vx.Message);}File.WriteAllLines(Path.Combine(backup,"TransactionReport.txt"),log);throw new InvalidOperationException(string.Join(Environment.NewLine,log),ex);}finally{VaultCatalogService.EndSession();}
 }
}
public sealed class IssuanceLock:IDisposable{
 FileStream? f; public static string PathFor(string catalogPath)=>Path.Combine(Path.GetDirectoryName(catalogPath)??"","LSE_PartNumber.lock");
 public static IssuanceLock Acquire(string catalogPath,List<string> log){string p=PathFor(catalogPath);var x=new IssuanceLock();for(int i=0;i<40;i++){try{x.f=new FileStream(p,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None,4096,FileOptions.DeleteOnClose);byte[] b=System.Text.Encoding.UTF8.GetBytes($"{Environment.UserName}@{Environment.MachineName} {DateTime.Now:s}");x.f.Write(b,0,b.Length);x.f.Flush();log.Add("Issuance lock: PASS");return x;}catch(IOException){Thread.Sleep(250);}}throw new InvalidOperationException("Another workstation is issuing a part number right now (lock file "+p+"). Try again in a moment.");}
 public void Dispose(){try{f?.Dispose();}catch{}f=null;}
}
